const variants = [
  ['beginner', 'conceptual', (title) => `Explain ${title} and the main problem it solves.`, 'Define its purpose, core components, and boundary with adjacent features.'],
  ['beginner', 'hands-on', (title) => `How would you configure a small first implementation of ${title} and verify that it works?`, 'State the prerequisites, minimum configuration, and one observable validation.'],
  ['intermediate', 'scenario', (title) => `A production team is considering ${title}. How would you decide whether it fits and implement it safely?`, 'Connect workload requirements to security, cost, dependencies, and measurable acceptance criteria.'],
  ['intermediate', 'troubleshooting', (title) => `${title} is configured but the expected result is missing or slow. What would you investigate?`, 'Use runtime evidence to isolate configuration, data, permissions, capacity, and feature limitations.'],
  ['advanced', 'design', (title) => `Design an enterprise-ready solution around ${title}. Which trade-offs and controls matter most?`, 'Cover failure domains, governance, observability, recovery, scalability, and cost.'],
  ['advanced', 'troubleshooting', (title) => `After a deployment involving ${title}, production results are incomplete or inconsistent. Describe a safe diagnosis and recovery.`, 'Preserve evidence, identify the last correct state, recover idempotently, reconcile results, and prevent recurrence.'],
];

function createQuestions(technology, units) {
  return units.flatMap(([slug, topic, title, summary, expectedConcepts, sourceTitle, url]) =>
    variants.map(([difficulty, type, question, emphasis], index) => {
      const record = {
        id: `candidate-${technology}-${slug}-${String(index + 1).padStart(2, '0')}`,
        technology,
        topic,
        difficulty,
        type,
        question: question(title),
        canonicalAnswer: `${summary} ${emphasis}`,
        expectedConcepts,
        followUps: [
          `Which limitation or cost of ${title} would you validate?`,
          `What evidence would prove that ${title} is working correctly?`,
        ],
        source: { title: sourceTitle, url, verified },
        reviewStatus: 'ai-reviewed',
        version: 1,
      };
      return { ...record, benchmark: benchmarkFor(record) };
    }),
  );
}

const packs = {
  aws: createQuestions('aws', aws),
  databricks: createQuestions('databricks', databricks),
  oracle: createQuestions('oracle', oracle),
  'power-bi': createQuestions('power-bi', powerBi),
  python: createQuestions('python', python),
};

const scriptDirectory = dirname(fileURLToPath(import.meta.url));
const outputDirectory = resolve(scriptDirectory, '../apps/web/data/candidates');
await mkdir(outputDirectory, { recursive: true });

for (const [technology, questions] of Object.entries(packs)) {
  if (questions.length !== 150) throw new Error(`Expected 150 ${technology} questions, received ${questions.length}`);
  const outputPath = resolve(outputDirectory, `${technology}.json`);
  await writeFile(outputPath, `${JSON.stringify(questions, null, 2)}\n`, 'utf8');
  console.log(`Wrote ${questions.length} questions to ${outputPath}`);
}
